import{_ as a,o as l,c as r,a0 as o}from"./chunks/framework.ZoVXsKRZ.js";const u=JSON.parse('{"title":"📖 麻将技巧总览","description":"","frontmatter":{"lastUpdated":true},"headers":[],"relativePath":"skills/index.md","filePath":"skills/index.md","lastUpdated":1784794489000}'),e={name:"skills/index.md"};function i(s,t,n,d,h,c){return l(),r("div",null,[...t[0]||(t[0]=[o(`<h1 id="📖-麻将技巧总览" tabindex="-1">📖 麻将技巧总览 <a class="header-anchor" href="#📖-麻将技巧总览" aria-label="Permalink to &quot;📖 麻将技巧总览&quot;">​</a></h1><p>麻将，作为中国传统文化中的&quot;国粹&quot;之一，不仅是娱乐，更是一门学问。无论你是刚摸牌的新手，还是身经百战的老手，这里都有适合你的内容。</p><h2 id="🎯-快速导航" tabindex="-1">🎯 快速导航 <a class="header-anchor" href="#🎯-快速导航" aria-label="Permalink to &quot;🎯 快速导航&quot;">​</a></h2><ul><li><strong><a href="/mahjong/skills/rules.html">各地麻将规则</a></strong> — 广东麻将、四川麻将、日本麻将……各地玩法一网打尽</li><li><strong><a href="/mahjong/skills/anti-cheat.html">防老千秘籍</a></strong> — 识破千术，守护钱包，线下打牌必看</li></ul><hr><h2 id="🀄-麻将基础入门" tabindex="-1">🀄 麻将基础入门 <a class="header-anchor" href="#🀄-麻将基础入门" aria-label="Permalink to &quot;🀄 麻将基础入门&quot;">​</a></h2><h3 id="牌型构成" tabindex="-1">牌型构成 <a class="header-anchor" href="#牌型构成" aria-label="Permalink to &quot;牌型构成&quot;">​</a></h3><p>一副标准麻将共 <strong>144 张</strong>（不含花牌为 136 张）：</p><table tabindex="0"><thead><tr><th>类别</th><th>牌型</th><th>数量</th></tr></thead><tbody><tr><td>万子</td><td>一万 ~ 九万</td><td>各 4 张，共 36 张</td></tr><tr><td>筒子</td><td>一筒 ~ 九筒</td><td>各 4 张，共 36 张</td></tr><tr><td>条子</td><td>一条 ~ 九条</td><td>各 4 张，共 36 张</td></tr><tr><td>字牌</td><td>东、南、西、北、中、发、白</td><td>各 4 张，共 28 张</td></tr><tr><td>花牌</td><td>春、夏、秋、冬、梅、兰、竹、菊</td><td>各 1 张，共 8 张</td></tr></tbody></table><h3 id="基本术语" tabindex="-1">基本术语 <a class="header-anchor" href="#基本术语" aria-label="Permalink to &quot;基本术语&quot;">​</a></h3><ul><li><strong>顺子</strong>：三张同花色且数字连续的牌，如「一万、二万、三万」</li><li><strong>刻子</strong>：三张完全相同的牌，如「三张五筒」</li><li><strong>杠子</strong>：四张完全相同的牌</li><li><strong>对子（将牌）</strong>：两张完全相同的牌</li><li><strong>碰</strong>：当别人打出一张牌，你手中有两张相同的，可以喊「碰」</li><li><strong>吃</strong>：上家打出的牌，能和你手中的两张组成顺子，可以喊「吃」</li><li><strong>杠</strong>：手中有三张相同的牌，别人再打出一张，或自己摸到第四张</li><li><strong>听牌</strong>：只差一张牌就能胡牌的状态</li><li><strong>胡牌</strong>：完成牌型，赢得本局</li></ul><h3 id="基本胡牌条件" tabindex="-1">基本胡牌条件 <a class="header-anchor" href="#基本胡牌条件" aria-label="Permalink to &quot;基本胡牌条件&quot;">​</a></h3><p>绝大多数麻将玩法都要求：<strong>4 组面子（顺子或刻子）+ 1 对将牌 = 14 张</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>示例胡牌牌型：</span></span>
<span class="line"><span>🀇🀈🀉（顺子）  🀙🀚🀛（顺子）  🀐🀐🀐（刻子）  🀀🀀🀀（刻子）  🀝🀝（将牌）</span></span></code></pre></div><hr><h2 id="🧠-进阶技巧" tabindex="-1">🧠 进阶技巧 <a class="header-anchor" href="#🧠-进阶技巧" aria-label="Permalink to &quot;🧠 进阶技巧&quot;">​</a></h2><h3 id="_1-看牌如看人" tabindex="-1">1. 看牌如看人 <a class="header-anchor" href="#_1-看牌如看人" aria-label="Permalink to &quot;1. 看牌如看人&quot;">​</a></h3><p>观察对手出牌习惯是进阶的第一步：</p><ul><li><strong>快出牌</strong>：摸到就用不上，大概率是废牌</li><li><strong>犹豫后出牌</strong>：可能在拆搭子，附近牌要小心</li><li><strong>一直不出某种花色</strong>：可能在憋大牌</li></ul><h3 id="_2-记牌是基本功" tabindex="-1">2. 记牌是基本功 <a class="header-anchor" href="#_2-记牌是基本功" aria-label="Permalink to &quot;2. 记牌是基本功&quot;">​</a></h3><p>高手能在脑中维护一个&quot;已出牌数据库&quot;：</p><ul><li>记录字牌（东南西北中发白）出了几张</li><li>关注自己需要的花色还有几张在牌山中</li><li>根据出牌情况判断对手可能听什么</li></ul><h3 id="_3-舍牌逻辑" tabindex="-1">3. 舍牌逻辑 <a class="header-anchor" href="#_3-舍牌逻辑" aria-label="Permalink to &quot;3. 舍牌逻辑&quot;">​</a></h3><blockquote><p>「宁弃莫出铳」—— 宁可拆牌也不要打危险牌</p></blockquote><ul><li><strong>前期</strong>：优先舍弃孤张（不成搭子的单牌）</li><li><strong>中期</strong>：跟着别人出过的牌走，降低点炮风险</li><li><strong>后期</strong>：对手可能已听牌，保守为上</li></ul><h3 id="_4-概率思维" tabindex="-1">4. 概率思维 <a class="header-anchor" href="#_4-概率思维" aria-label="Permalink to &quot;4. 概率思维&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">算一算</p><p>假设你需要一张「五万」听牌，牌山还剩约 40 张，万字牌还剩约 10 张，其中五万还剩几张？根据已出牌推断，如果别人已经打了两张五万，那你的概率就极低了——及时转听其他牌。</p></div><hr><h2 id="📚-推荐学习路径" tabindex="-1">📚 推荐学习路径 <a class="header-anchor" href="#📚-推荐学习路径" aria-label="Permalink to &quot;📚 推荐学习路径&quot;">​</a></h2><ol><li><strong>零基础</strong> → 先了解牌型 → 看懂基本胡牌条件 → 找朋友打几局</li><li><strong>新手</strong> → 学习基本舍牌逻辑 → 了解常见役种 → 多打多练</li><li><strong>进阶</strong> → 学习防守打法 → 训练记牌能力 → 研究概率决策</li><li><strong>高手</strong> → 钻研各地规则差异 → 学习心理博弈 → 参加比赛</li></ol><hr><p><em>更多技巧持续更新中，欢迎常回来看看！</em></p>`,32)])])}const p=a(e,[["render",i]]);export{u as __pageData,p as default};
